Check(usage.Day(epoch.Date).Apps["browser"]==1&&usage.Day(epoch.Date).Apps["editor"]==1,"Usage charges elapsed time to the previous foreground app");
Check(usage.Day(epoch.Date).AppSwitches==1,"First app is not an app switch");
recorder.Sample(usage,epoch.AddSeconds(1),"bad",true);Check(!usage.Day(epoch.Date).Apps.ContainsKey("bad"),"Out-of-order samples cannot add usage");
