recorder.Sample(usage,epoch.AddMinutes(40).AddSeconds(1),null,true);recorder.Sample(usage,epoch.AddMinutes(40).AddSeconds(2),null,true);Check(usage.Day(epoch.Date).Apps["editor"]==2,"Idle/excluded samples do not add idle intervals");
