 using var file=File.OpenRead(args[1]);using var pe=new System.Reflection.PortableExecutable.PEReader(file);var metadata=pe.GetMetadataReader();var entries=metadata.ManifestResources.Select(h=>metadata.GetManifestResource(h)).ToArray();var resources=entries.Select(r=>metadata.GetString(r.Name)).ToArray();Check(resources.Contains("OrbitIsland.Assets.Icons.json"),"Standard icons are embedded in the Windows assembly");Check(resources.Any(n=>n.EndsWith(".g.resources")),"Compiled WPF theme resources are packaged");var resource=entries.Single(r=>metadata.GetString(r.Name)=="OrbitIsland.Assets.Icons.json");var block=pe.GetSectionData(pe.PEHeaders.CorHeader!.ResourcesDirectory.RelativeVirtualAddress);var reader=block.GetReader((int)resource.Offset,block.Length-(int)resource.Offset);int size=reader.ReadInt32();using var icons=System.Text.Json.JsonDocument.Parse(reader.ReadBytes(size));Check(icons.RootElement.EnumerateObject().Count()>=70&&icons.RootElement.GetProperty("music").GetString()!.Length>0,"Packaged icon catalog includes media and weather icons");
